const SYMBOLS = BOOK.symbols;

async function yahooPrice(sym) {
  const url = "https://query1.finance.yahoo.com/v8/finance/chart/"
    + encodeURIComponent(sym) + "?interval=1d&range=1d";
  const res = await fetch(url, { headers: { "User-Agent": UA } });
  if (!res.ok) throw new Error("yahoo " + res.status + " for " + sym);
  const d = await res.json();
  const meta = d && d.chart && d.chart.result && d.chart.result[0] && d.chart.result[0].meta;
  const px = meta && meta.regularMarketPrice;
  if (typeof px !== "number" || !isFinite(px)) throw new Error("no price for " + sym);
  return px;
}

function round2(n) { return Math.round(n * 100) / 100; }

// Latest ticks from the Railway bus. Returns a prices map, or null when
// the bus is not configured or the call fails (caller falls back to Yahoo).
async function busPrices() {
  if (!BUS_URL || !BUS_TOKEN) return null;
  let res;
  try {
    res = await fetch(BUS_URL + "/snapshot", {
      headers: { Authorization: "Bearer " + BUS_TOKEN },
    });
  } catch (e) {
    return null;
  }
  if (!res.ok) return null;
  let d;
  try {
    d = await res.json();
  } catch (e) {
    return null;
  }
  const ticks = d && d.ticks;
  if (!ticks || typeof ticks !== "object") return null;
  const prices = {};
  for (const sym of SYMBOLS) {
    const t = ticks[sym];
    if (t && typeof t.price === "number" && isFinite(t.price)) {
      prices[sym] = t.price;
    }
  }
  return Object.keys(prices).length ? prices : null;
}

exports.handler = async () => {
  const headers = { "Content-Type": "application/json", "Cache-Control": "no-store" };
  let prices = await busPrices();
  let feed = "bus-live";
  let quotesAsOf = "live ticks from the Desk feed pipeline (Railway bus)";
  if (prices) {
    // Fill any symbol the bus has no tick for yet from Yahoo.
    const missing = SYMBOLS.filter((s) => !(s in prices));
    if (missing.length) {
      try {
        const vals = await Promise.all(missing.map(yahooPrice));
        missing.forEach((s, i) => { prices[s] = vals[i]; });
        quotesAsOf += "; " + missing.join(", ") + " from Yahoo until the first tick";
      } catch (e) {
        return { statusCode: 502, headers,
          body: JSON.stringify({ error: "quote_failed", detail: String((e && e.message) || e) }) };
      }
    }
  } else {
    feed = "yahoo-live";
    quotesAsOf = "live, fetched now from Yahoo Finance v8 chart";
    try {
      const vals = await Promise.all(SYMBOLS.map(yahooPrice));
      prices = Object.fromEntries(SYMBOLS.map((s, i) => [s, vals[i]]));
    } catch (e) {
      return { statusCode: 502, headers,
        body: JSON.stringify({ error: "quote_failed", detail: String((e && e.message) || e) }) };
    }
  }

  const positions = BOOK.fills.map((f) => {
    const last = prices[f.symbol];
    return { symbol: f.symbol, name: f.name || f.symbol, bucket: f.bucket || "swing", qty: f.qty, fill: f.fill, last,
      pnl: round2((last - f.fill) * f.qty), stop: f.stop, target: f.target,
      target2: f.target2, kill: f.kill, order_id: f.order_id, filled_at: f.filled_at };
  });
  const equity = round2(positions.reduce((s, p) => s + p.last * p.qty, 0));
  const optionsAtCost = round2(BOOK.options.reduce((s, o) => s + o.at_cost, 0));
  const total = round2(equity + optionsAtCost + BOOK.cash);

  // Attention: nearest live level wins. A position within 1% of its
  // target or stop needs Milly; an option inside 5 days of expiry is
  // named until it closes.
  let attention = "Nothing needs you right now.";
  for (const p of positions) {
    if (p.target && Math.abs(p.last - p.target) / p.target <= 0.01) {
      attention = p.symbol + " is within 1% of its target $" + p.target + ". This needs you.";
      break;
    }
    if (p.stop && Math.abs(p.last - p.stop) / p.stop <= 0.01) {
      attention = p.symbol + " is within 1% of its stop $" + p.stop + ". This needs you.";
      break;
    }
  }
  if (attention.startsWith("Nothing") && BOOK.options.length) {
    attention = "Options open: " + BOOK.options.map((o) => o.instrument).join("; ")
      + " (at cost; marks run on the levels watch).";
  }

  return { statusCode: 200, headers, body: JSON.stringify({
    generated: new Date().toISOString(),
    firm: "OpOne Capital",
    feed,
    book: { real: { total, cash: BOOK.cash, equity, options_at_cost: optionsAtCost,
                    positions: positions.length + BOOK.options.length },
            paper: BOOK.paper },
    attention,
    positions,
    closed: BOOK.closed || [],
    options: BOOK.options,
    conditionals: BOOK.conditionals.map((c) => ({ ...c, last: prices[c.symbol] })),
    gold: { ...BOOK.gold },
    buckets: BOOK.buckets || [],
    leaps_paper: BOOK.leaps_paper || [],
    day_trading: BOOK.day_trading || [],
    ladders: BOOK.ladders || [],
    cash_as_of: BOOK.cash_as_of || "",
    record: RECORD,
    index: INDEX,
    quotes_as_of: quotesAsOf + "; gold record as of " + BOOK.gold.as_of,
  }) };
};
